SELECT id, session_id, request_id, user_id, agent_id, model_name, source,
       request_json, response_json, error_text, status, input_tokens, output_tokens, total_tokens, cost_ms, create_time
FROM request_response_log
WHERE session_id = #{sessionId}

    AND request_id = #{requestId}

ORDER BY id DESC
